<?php

namespace App\Enums;

use InvalidArgumentException;

/**
 * Represents the visual/behavioral state of a pet.
 * Each state maps to a state video generated by fal.ai (Kling 3.0 Pro, M4-03) and
 * stored in pet_media.
 *
 * Species (M5-R06-07, CAT_SPEC §8): the six classic states exist for both
 * species with their own video prompt (a cat's `low_energy` is "bored" —
 * its energy is the play meter). Behaviour videos are per species: dogs
 * `accident` / `chewing`, cats `scratching` (appliesTo()).
 */
enum PetStateEnum: string
{
    case Idle = 'idle';
    case Sleeping = 'sleeping';
    case LowEnergy = 'low_energy';
    case Hungry = 'hungry';
    case Sick = 'sick';
    case Playing = 'playing';

    // M5-R02 behaviour videos (premium set only, MediaEntitlementService).
    // `pets.pet_state` never takes these values: a dirty dog stays `sick`
    // (old app builds know only the six states); the apps pick these videos
    // from the payload's `behaviour.scene` while such an event is open.
    case Accident = 'accident';
    case Chewing = 'chewing';

    // M5-R06-07: the cat's behaviour video ("opraskala je kavč", CAT_SPEC Q10),
    // shown while a scratching mess is open (`behaviour.scene` = scratching).
    // Video slots only — never a `pets.pet_state` value. No `accident` for cats.
    case Scratching = 'scratching';

    /**
     * The values `pets.pet_state` can take (pets_pet_state_check): the six
     * classic states. Behaviour states are video slots only.
     *
     * @return list<self>
     */
    public static function petStates(): array
    {
        return [self::Idle, self::Sleeping, self::LowEnergy, self::Hungry, self::Sick, self::Playing];
    }

    /** A behaviour video (M5-R02 / M5-R06-07) — shown from `behaviour.scene`, gated by MediaEntitlementService. */
    public function isBehaviour(): bool
    {
        return in_array($this, [self::Accident, self::Chewing, self::Scratching], true);
    }

    /** Whether a pet of the species can ever show this state (and get its video). */
    public function appliesTo(Species $species): bool
    {
        return match ($this) {
            self::Accident, self::Chewing => $species === Species::Dog,
            self::Scratching => $species === Species::Cat,
            default => true,
        };
    }

    /**
     * M5-T08 (APP_REFINEMENT_SPEC §7): the pose of this state's KEY IMAGE — an
     * edit of the stage's reference image (Nano Banana Pro Edit), the start and
     * end frame of the state's loop. `idle` has no key image of its own: the
     * reference image (standing / sitting calmly) is the idle pose.
     */
    public function keyPose(Species $species = Species::Dog): string
    {
        if (! $this->appliesTo($species)) {
            throw new InvalidArgumentException("A {$species->value} has no '{$this->value}' pose.");
        }

        if ($species === Species::Cat) {
            return match ($this) {
                self::Idle => 'sitting calmly and looking around, exactly as in the reference image',
                self::Sleeping => 'curled up in a tight ball asleep on a soft blanket on the floor, eyes closed, relaxed',
                self::LowEnergy => 'lying on a windowsill and gazing out of the window with a bored expression',
                self::Hungry => 'sitting next to an empty cat food bowl on the floor and looking down at it',
                self::Sick => 'lying quietly in a hunched loaf position with half-closed eyes',
                self::Playing => 'crouched low and alert, eyes fixed on a feather toy dangling on a string from above the frame',
                self::Scratching => 'standing on its hind legs with the front claws on the side of a fabric sofa, scratching it',
                self::Accident, self::Chewing => throw new InvalidArgumentException("A cat has no '{$this->value}' pose."),
            };
        }

        return match ($this) {
            self::Idle => 'standing calmly on all four paws and looking around, exactly as in the reference image',
            self::Sleeping => 'lying curled up asleep on the floor, eyes closed, relaxed',
            self::LowEnergy => 'lying down on the floor with the head resting on the front paws and droopy eyelids, tired',
            self::Hungry => 'sitting next to an empty dog food bowl on the floor and looking down at it',
            self::Sick => 'lying down quietly on the floor with sad tired eyes and the head low',
            self::Playing => 'in a playful bow: front legs stretched forward on the floor, rear end up, tail raised, happy open mouth',
            self::Accident => 'standing next to a small clear puddle on a wooden floor, ears slightly back, a guilty apologetic look',
            self::Chewing => 'lying on the floor holding a soft house slipper between the front paws and chewing it',
            self::Scratching => throw new InvalidArgumentException('A dog has no scratching pose.'),
        };
    }

    /**
     * M5-T08: the motion of the LOOP of this state — clearly visible natural movement
     * that stays in the key pose (fix 2026-10-23: the loop is sent with its key image as
     * the start frame only; a same start / end frame froze the clip on Kling 3.0 Pro).
     */
    public function loopMotion(Species $species = Species::Dog): string
    {
        if (! $this->appliesTo($species)) {
            throw new InvalidArgumentException("A {$species->value} has no '{$this->value}' loop.");
        }

        if ($species === Species::Cat) {
            return match ($this) {
                self::Idle => 'staying in the same position as in the image, turning the head to look around, blinking, the ears swivelling, the tail curling and flicking, a visible breath and a small shift of weight',
                self::Sleeping => 'asleep and staying curled up the whole time, the flank clearly rising and falling with each breath, small twitches of the ears, whiskers and paws',
                self::LowEnergy => 'staying on the windowsill, the tail tip flicking, the head turning to look outside and back, slow visible breathing',
                self::Hungry => 'staying seated by the bowl, looking down at it, sniffing it and looking up again, licking its lips, the tail swishing',
                self::Sick => 'staying in the loaf position, visible slow breathing, the eyes half closing and opening, a small ear twitch, not getting up',
                self::Playing => 'staying crouched, the hindquarters wiggling clearly, the head and eyes following something moving above the frame, the tail twitching',
                self::Scratching => 'scratching the sofa with steady strokes of the front paws, staying on its hind legs',
                self::Accident, self::Chewing => throw new InvalidArgumentException("A cat has no '{$this->value}' loop."),
            };
        }

        return match ($this) {
            self::Idle => 'standing in the same spot, breathing visibly, turning the head to look around and sniffing the air, the tail wagging, the ears moving, shifting its weight from paw to paw, without sitting or lying down',
            self::Sleeping => 'asleep and staying curled up the whole time, the chest clearly rising and falling with each breath, small dreaming twitches of the ears, lips and paws',
            self::LowEnergy => 'lying down, slow visible tired breathing, the eyelids drooping and blinking, the head lifting a little and resting again, a weak tail thump',
            self::Hungry => 'staying seated by the bowl, sniffing the bowl, looking up again and licking its lips, the tail sweeping the floor',
            self::Sick => 'lying down with visible slow breathing, the eyes blinking, the head lifting a little and resting again, not getting up',
            self::Playing => 'bouncing excitedly on the front paws in the play bow, the tail wagging fast, the head tilting, staying in place',
            self::Accident => 'standing by the puddle, the tail wagging low, glancing down at the puddle and up at the camera, the ears moving, staying in place',
            self::Chewing => 'chewing and tugging at the slipper with clear jaw and head movement, the tail wagging, staying lying down',
            self::Scratching => throw new InvalidArgumentException('A dog has no scratching loop.'),
        };
    }

    /**
     * Get a human-readable description of the pet state.
     */
    public function description(): string
    {
        return match ($this) {
            self::Idle => 'Pet is relaxed and alert',
            self::Sleeping => 'Pet is sleeping peacefully',
            self::LowEnergy => 'Pet looks tired and lethargic',
            self::Hungry => 'Pet is staring at its food bowl',
            self::Sick => 'Pet looks unwell and greyed out',
            self::Playing => 'Pet is energetic and playful',
            self::Accident => 'Puppy had an accident indoors (puddle)',
            self::Chewing => 'Dog is chewing a slipper',
            self::Scratching => 'Cat is scratching the sofa',
        };
    }

    /**
     * What the dog does in this state's video (M4-03). Combined with the pet's
     * DNA description by PetAppearancePrompt::videoPrompt(). Subtle, realistic
     * motion only — the video loops behind the HUD; the app adds UI effects
     * (e.g. the grey "sick" overlay) itself.
     *
     * Cats (M5-R06-07, CAT_SPEC §8 "videi stanj" — draft (D)): their own
     * modifiers. A state the species never has throws.
     */
    public function promptModifier(Species $species = Species::Dog): string
    {
        if (! $this->appliesTo($species)) {
            throw new InvalidArgumentException("A {$species->value} has no '{$this->value}' video.");
        }

        if ($species === Species::Cat) {
            return match ($this) {
                self::Idle => 'sitting calmly and looking around, blinking slowly, the tail gently curling and moving, an occasional ear twitch',
                self::Sleeping => 'curled up in a tight ball asleep on a soft blanket, eyes closed, slow rhythmic breathing, a small ear twitch',
                // Energy is the play meter for a cat (M5-R06-04): low = bored, not tired.
                self::LowEnergy => 'lying on a windowsill and gazing out of the window with a bored expression, the tail tip slowly flicking, barely moving',
                self::Hungry => 'sitting next to an empty cat food bowl, looking down at it and then up expectantly, licking its lips',
                // No distressing scenes (CAT_SPEC §8).
                self::Sick => 'lying quietly in a hunched loaf position with half-closed eyes, slow calm breathing, not getting up',
                // The toy hangs from above — no hand, no person in frame.
                self::Playing => 'leaping and batting with its front paws at a feather toy dangling on a string from above the frame, playful and alert',
                self::Scratching => 'standing on its hind legs and scratching the side of a fabric sofa with its front claws, stretching, focused',
                self::Accident, self::Chewing => throw new InvalidArgumentException("A cat has no '{$this->value}' video."),
            };
        }

        return match ($this) {
            self::Idle => 'sitting calmly and looking around with a relaxed expression, gentle breathing, an occasional slow tail wag and ear twitch',
            self::Sleeping => 'curled up asleep on the floor, eyes closed, slow rhythmic breathing, a small ear twitch',
            self::LowEnergy => 'lying down with droopy eyelids, head resting on the front paws, slow tired breathing, barely moving',
            self::Hungry => 'sitting next to an empty dog food bowl, looking down at it and then up hopefully, licking its lips',
            self::Sick => 'lying down quietly with sad tired eyes, head low, slow shallow breathing, not getting up',
            self::Playing => 'in a playful bow with the tail wagging, bouncing gently on the front paws in place, happy open mouth',
            self::Accident => 'standing next to a small clear puddle on a wooden floor, looking up with a guilty apologetic expression, ears slightly back, a slow low tail wag',
            self::Chewing => 'lying on the floor chewing a soft house slipper held between the front paws, focused and playful, an occasional tail wag',
            self::Scratching => throw new InvalidArgumentException('A dog has no scratching video.'),
        };
    }
}
